negativeExample:
package org.eclipse.search.internal.ui.text;

import org.eclipse.core.runtime.IStatus;
import org.eclipse.core.runtime.Status;
import org.eclipse.search.internal.ui.SearchPlugin;
import org.eclipse.core.runtime.CoreException;

public class MarkerHighlighter {
    public void doNotMatchDirectStatusLog() {
        // Rule should not match because the argument is directly an IStatus, not an exception's getStatus()
        IStatus someStatus = Status.CANCEL_STATUS;
        SearchPlugin.log(someStatus);
    }

    public void doNotMatchNonCoreException() {
        // Rule should not match because the caught exception 'e' is not CoreException,
        // even if it hypothetically has a getStatus() method.
        class MyCustomException extends RuntimeException {
            private final IStatus status;
            public MyCustomException(String message, IStatus status) {
                super(message);
                this.status = status;
            }
            public IStatus getStatus() { return status; }
        }
        try {
            throw new MyCustomException("custom error", Status.OK_STATUS);
        } catch (MyCustomException e) {
            SearchPlugin.log(e.getStatus()); // $e is MyCustomException, not CoreException. Should not match.
        }
    }
}
